/*
 * The full catalog the server hands out: featured picks first, then the automatic index.
 * Server only. Edit api/_featured.js by hand; api/_index.js is generated by scripts/index-skills.mjs.
 */
import { FEATURED, UPDATED as FEATURED_UPDATED } from "./_featured.js";
import { INDEX, INDEXED_AT } from "./_index.js";

const skillOf = e => {
  if (e.skill) return e.skill.toLowerCase();
  const m = (e.cmd || "").match(/--skill\s+"?([\w:.-]+)/);
  return m ? m[1].toLowerCase() : e.path ? e.path.split("/").pop().toLowerCase() : null;
};
// An indexed skill is dropped when a featured entry already covers that exact skill.
const covered = new Set(FEATURED.map(f => `${f.repo.toLowerCase()}#${skillOf(f)}`).filter(k => !k.endsWith("#null")));
const coveredPath = new Set(FEATURED.filter(f => f.path).map(f => `${f.repo.toLowerCase()}#${f.path}`));

export const UPDATED = INDEXED_AT > FEATURED_UPDATED ? INDEXED_AT : FEATURED_UPDATED;
export const SKILLS = [
  ...FEATURED,
  ...INDEX.filter(e => !covered.has(`${e.repo.toLowerCase()}#${skillOf(e)}`) && !coveredPath.has(`${e.repo.toLowerCase()}#${e.path}`))
];
